<?= $this->extend('layouts/app') ?><?= $this->section('content') ?>
<div class="page-head"><div><h1>Team Schedules</h1><p>Schedules appear in brackets and inherit the sport category.</p></div><button class="btn primary" data-modal="schedule-modal">+ Add Schedule</button></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Sport</th><th>Round</th><th>Location</th><th>Teams</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($schedules as $s): ?><tr><td><b><?= esc($s['sport_name']) ?></b><small class="muted"><?= esc($s['category']) ?></small></td><td><?= esc($s['round']) ?></td><td><?= esc($s['location_name']??'—') ?></td><td><?= esc($s['team_a_name']??'Open') ?> vs <?= esc($s['team_b_name']??'Open') ?></td><td><?= esc(date('M j, Y g:i A',strtotime($s['match_date']))) ?></td><td><span class="badge neutral"><?= strtoupper(esc($s['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
<dialog id="schedule-modal"><form method="post" action="<?= site_url('schedules') ?>" class="modal-card wide"><?= csrf_field() ?><div class="modal-head"><h2>Add Team Schedule</h2><button type="button" data-close>×</button></div><label>Sport<select name="sport_id" required><option value="">Select sport</option><?php foreach($sports as $s): ?><option value="<?= $s['id'] ?>"><?= esc($s['name'].' · '.$s['category']) ?></option><?php endforeach; ?></select></label><label>Location<select name="location_id" required><option value="">Select location</option><?php foreach($locations as $l): ?><option value="<?= $l['id'] ?>"><?= esc($l['name']) ?></option><?php endforeach; ?></select></label><label>Round<input name="round" placeholder="Elimination / Semi-final / Final / Bronze"></label><label>Match Date<input type="datetime-local" name="match_date" required></label><div class="form-grid"><label>Team A<select name="team_a_id"><option value="">Open / judged</option><?php foreach($teams as $t): ?><option value="<?= $t['id'] ?>"><?= esc($t['name']) ?></option><?php endforeach; ?></select></label><label>Team B<select name="team_b_id"><option value="">Open / judged</option><?php foreach($teams as $t): ?><option value="<?= $t['id'] ?>"><?= esc($t['name']) ?></option><?php endforeach; ?></select></label></div><button class="btn primary full">Save Schedule</button></form></dialog>
<?= $this->endSection() ?>
